        assertFalse(shipments().progressV2(v.id(),"old-v2",0,"SHIPPED","IN_TRANSIT",at).applied());var transit=shipments().progressV2(v.id(),"new-transit",3,"SHIPPED","IN_TRANSIT",at);assertTrue(transit.applied());shipments().tracking(v.id(),shipmentAuthority(f),new com.example.marketplace.fulfillment.api.Shipments.TrackingCommand("correction",transit.version(),"NEW-2","번호 정정"));var done=shipments().progressV2(v.id(),"new-delivered",3,"IN_TRANSIT","DELIVERED",at.minusSeconds(20).plusNanos(123456789));assertTrue(done.applied());assertEquals(1,deliveryCount(f));var completed=shipments().seller(ownSeller(f),shipmentAuthority(f)).getFirst();assertEquals(at.minusSeconds(20).plusNanos(123457000),completed.deliveredAt());assertEquals("MOCK-TRACK-1",completed.trackingHistory().getLast().previousTracking());assertEquals("NEW-2",completed.trackingHistory().getLast().nextTracking());assertEquals("번호 정정",completed.trackingHistory().getLast().reason());
